// AC: @agent-invocation-lifecycle ac-6
describe("Streaming event logging", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-invoc-ac6-");
    registerMockAdapter({
      MOCK_ACP_RESPONSE_TEXT: "Streaming output test response",
    });
  });

  afterEach(async () => {
