describe("Host environment variable sanitization", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-invoc-ac12-");
    registerMockAdapter();
  });

  afterEach(async () => {
    // Restore any env vars we set during tests
    for (const key of SANITIZED_ENV_VARS) {
      delete process.env[key];
    }
    await cleanupTempDir(testDir);
  });

  it("should strip CLAUDECODE and CLAUDE_CODE_SESSION from spawned agent environment", async () => {
    // Simulate running inside a Claude Code environment
    process.env.CLAUDECODE = "1";
    process.env.CLAUDE_CODE_SESSION = "parent-session-id";

    const agent = makeTestAgent();

    // Spy on spawnAndInitialize to capture the env passed to the child process
    const originalSpawn = spawnerModule.spawnAndInitialize;
    let capturedEnv: Record<string, string | undefined> | undefined;

    const spawnSpy = vi.spyOn(spawnerModule, "spawnAndInitialize").mockImplementation(
      async (adapter, options) => {
        // Capture what spawnAgent would compute for the env by calling through
        // to the real implementation
        spawnSpy.mockRestore();
        const result = await originalSpawn(adapter, options);

        // Since we can't directly inspect the env after spawn, verify via
        // spawnAgent which constructs processEnv before calling spawn.
        // We'll verify the constant list instead.
        return result;
      },
    );

    try {
      const result = await runInvocation({
        agent,
        specDir: testDir,
        cwd: process.cwd(),
        taskRef: "@" + testUlid("TASK"),
        prompt: "Test env sanitization",
        trigger: "task.ready",
      });

      expect(result.outcome).toBe("success");
    } finally {
      spawnSpy.mockRestore();
    }
  });

  it("should strip all SANITIZED_ENV_VARS from the env passed to spawn", async () => {
    // Set all sanitized vars in process.env
    process.env.CLAUDECODE = "1";
    process.env.CLAUDE_CODE_SESSION = "parent-session-id";

    // Import spawn to spy on it directly
    const childProcessModule = await import("node:child_process");
    let spawnedEnv: NodeJS.ProcessEnv | undefined;

    const spawnSpy = vi.spyOn(childProcessModule, "spawn").mockImplementation(
      ((_command: string, _args: readonly string[], options: { env?: NodeJS.ProcessEnv }) => {
        spawnedEnv = options?.env;
        // Return a mock ChildProcess
        const emitter = new EventEmitter();
        const mockProcess = Object.assign(emitter, {
          stdin: null,
          stdout: null,
          stderr: null,
          pid: 12345,
          killed: false,
          kill: vi.fn(() => true),
          ref: vi.fn(),
          unref: vi.fn(),
          exitCode: null,
          signalCode: null,
          connected: false,
          disconnect: vi.fn(),
          send: vi.fn(),
          stdio: [null, null, null] as unknown[],
          channel: undefined,
          [Symbol.dispose]: vi.fn(),
        });
        // Emit exit immediately so spawnAgent doesn't hang
        setTimeout(() => emitter.emit("exit", 1, null), 10);
        return mockProcess;
      }) as typeof childProcessModule.spawn,
    );

    try {
      // spawnAgent will throw because stdin/stdout are null, but we can
      // still verify the env was sanitized before spawn was called
      const adapter = { command: "node", args: ["test.js"], env: {}, description: "test" };
      try {
        spawnerModule.spawnAgent(adapter, { cwd: testDir });
      } catch {
        // Expected: "Failed to create pipes for agent process"
      }

      expect(spawnedEnv).toBeDefined();
      for (const key of SANITIZED_ENV_VARS) {
        expect(spawnedEnv).not.toHaveProperty(key);
      }
    } finally {
      spawnSpy.mockRestore();
    }
  });

  it("should preserve other process.env variables when stripping host vars", async () => {
    // Set a sanitized var AND a normal var
    process.env.CLAUDECODE = "1";
    const originalPath = process.env.PATH;

    const childProcessModule = await import("node:child_process");
    let spawnedEnv: NodeJS.ProcessEnv | undefined;

    const spawnSpy = vi.spyOn(childProcessModule, "spawn").mockImplementation(
      ((_command: string, _args: readonly string[], options: { env?: NodeJS.ProcessEnv }) => {
        spawnedEnv = options?.env;
        const emitter = new EventEmitter();
        const mockProcess = Object.assign(emitter, {
          stdin: null,
          stdout: null,
          stderr: null,
          pid: 12345,
          killed: false,
          kill: vi.fn(() => true),
          ref: vi.fn(),
          unref: vi.fn(),
          exitCode: null,
          signalCode: null,
          connected: false,
          disconnect: vi.fn(),
          send: vi.fn(),
          stdio: [null, null, null] as unknown[],
          channel: undefined,
          [Symbol.dispose]: vi.fn(),
        });
        setTimeout(() => emitter.emit("exit", 1, null), 10);
        return mockProcess;
      }) as typeof childProcessModule.spawn,
    );

    try {
      const adapter = { command: "node", args: ["test.js"], env: {}, description: "test" };
      try {
        spawnerModule.spawnAgent(adapter, { cwd: testDir });
      } catch {
        // Expected
      }

      expect(spawnedEnv).toBeDefined();
      // CLAUDECODE stripped
      expect(spawnedEnv).not.toHaveProperty("CLAUDECODE");
      // PATH preserved
      expect(spawnedEnv!.PATH).toBe(originalPath);
    } finally {
      spawnSpy.mockRestore();
    }
  });

  it("should allow adapter.env and options.env to override sanitized vars if explicitly set", async () => {
    // Edge case: if adapter explicitly sets CLAUDECODE, it should be present
    // because adapter.env merges AFTER sanitization
    process.env.CLAUDECODE = "1";

    const childProcessModule = await import("node:child_process");
    let spawnedEnv: NodeJS.ProcessEnv | undefined;

    const spawnSpy = vi.spyOn(childProcessModule, "spawn").mockImplementation(
      ((_command: string, _args: readonly string[], options: { env?: NodeJS.ProcessEnv }) => {
        spawnedEnv = options?.env;
        const emitter = new EventEmitter();
        const mockProcess = Object.assign(emitter, {
          stdin: null,
          stdout: null,
          stderr: null,
          pid: 12345,
          killed: false,
          kill: vi.fn(() => true),
          ref: vi.fn(),
          unref: vi.fn(),
          exitCode: null,
          signalCode: null,
          connected: false,
          disconnect: vi.fn(),
          send: vi.fn(),
          stdio: [null, null, null] as unknown[],
          channel: undefined,
          [Symbol.dispose]: vi.fn(),
        });
        setTimeout(() => emitter.emit("exit", 1, null), 10);
        return mockProcess;
      }) as typeof childProcessModule.spawn,
    );

    try {
      // Adapter explicitly sets CLAUDECODE — should override the sanitization
      const adapter = {
        command: "node",
        args: ["test.js"],
        env: { CLAUDECODE: "adapter-override" },
        description: "test",
      };
      try {
        spawnerModule.spawnAgent(adapter, { cwd: testDir });
      } catch {
        // Expected
      }

      expect(spawnedEnv).toBeDefined();
      // Adapter's explicit value should win over sanitization
      expect(spawnedEnv!.CLAUDECODE).toBe("adapter-override");
    } finally {
      spawnSpy.mockRestore();
    }
  });

  it("SANITIZED_ENV_VARS should contain the expected variables", () => {
    // Guard against accidental removal of vars from the sanitization list
    expect(SANITIZED_ENV_VARS).toContain("CLAUDECODE");
    expect(SANITIZED_ENV_VARS).toContain("CLAUDE_CODE_SESSION");
  });
});

