   288→      sendError(msg.id || null, -32600, "Invalid Request");
   289→      return;
   290→    }
   291→
   292→    // Handle responses to outgoing requests (no 'method' field, has 'result' or 'error')
   293→    if (!msg.method && msg.id !== undefined) {
   294→      const pending = pendingRequests.get(msg.id);
   295→      if (pending) {
   296→        pendingRequests.delete(msg.id);
   297→        if (msg.error) {
   298→          pending.reject(new Error(msg.error.message || 'Request failed'));
   299→        } else {
   300→          pending.resolve(msg.result);
   301→        }
   302→      }
   303→      return;
   304→    }
   305→
   306→    if (!msg.method) {
   307→      sendError(msg.id || null, -32600, "Invalid Request");
   308→      return;
   309→    }
   310→
   311→    switch (msg.method) {
   312→      case "initialize":
   313→        await handleInitialize(msg.id, msg.params);
   314→        break;
   315→      case "session/new":
   316→        await handleNewSession(msg.id, msg.params);
   317→        break;
   318→      case "session/prompt":
   319→        await handlePrompt(msg.id, msg.params);
   320→        break;
   321→      case "session/request_permission":
   322→        await handleRequestPermission(msg.id, msg.params);
   323→        break;
   324→      default:
   325→        sendError(msg.id, -32601, `Method not found: ${msg.method}`);
   326→    }
   327→  } catch (err) {
   328→    sendError(null, -32700, "Parse error");
   329→  }
   330→}
